<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
try {
    $data=json_decode(file_get_contents($argv[1]??''),true,512,JSON_THROW_ON_ERROR);
    foreach(['tables','columns','indexes','relationships','engine','session_timezone'] as $key)if(!isset($data[$key]))throw new RuntimeException('Inventory required.');
    $cell=static fn($v):string=>str_replace(["|","\r","\n"],["\\|",'', ' '],$v===null?'NULL':(string)$v);
    $md="# CLEVO schema inventory\n\nGenerated from actual migrated disposable metadata on ".gmdate('Y-m-d').". Engine: `".$cell($data['engine'])."`; session timezone: `".$cell($data['session_timezone'])."`. Tables: ".count($data['tables'])."; columns: ".count($data['columns'])."; index columns: ".count($data['indexes'])."; foreign-key columns: ".count($data['relationships']).". This is not a live production inventory.\n\nSource: `scripts/database-inventory.php` output after the applied versioned migrations (including booking005,payments006,tracking007,notifications008,privacy009,cleanup010 and idempotency security011 when present). Reproduce with `php scripts/render-schema-docs.php <protected-inventory.json>`. No customer data is included; sensitive defaults are redacted. Existing FK delete rules are preserved when present, so a deployed variant may differ from this copy. Read [DATABASE_CHANGES.md](DATABASE_CHANGES.md), [BOOKING_WORKFLOW.md](BOOKING_WORKFLOW.md) and [PAYMENT_INTEGRATION.md](PAYMENT_INTEGRATION.md) for semantics, anomalies, compatibility and release gates; [DATABASE_ERD.md](DATABASE_ERD.md) for the graph.\n";
    $erd="# CLEVO entity relationship diagram\n\nGenerated from the same actual metadata as [DATABASE_SCHEMA.md](DATABASE_SCHEMA.md). Every declared FK is represented. Parent optionality follows child nullability; child maximum-one is shown for single-column unique FKs. Composite unique constraints may impose additional limits; see the full index inventory. Role/station equality, payment state, booking lifecycle and immutable history are application policies, not implied by the graph.\n\n```mermaid\nerDiagram\n";
    foreach($data['tables'] as $table){
        $name=$table['TABLE_NAME'];$columns=array_values(array_filter($data['columns'],fn($c)=>$c['TABLE_NAME']===$name));$indexes=array_values(array_filter($data['indexes'],fn($i)=>$i['TABLE_NAME']===$name));$relationships=array_values(array_filter($data['relationships'],fn($r)=>$r['TABLE_NAME']===$name));
        $md.="\n## `$name`\n\nEngine: `".$cell($table['ENGINE'])."`; collation: `".$cell($table['TABLE_COLLATION'])."`.\n\n| Column | SQL type | Null | Default | Extra |\n|---|---|---|---|---|\n";
        foreach($columns as $c){$default=$c['COLUMN_DEFAULT'];if($default!==null&&preg_match('/password|secret|token|otp|accesscode|cipher/i',$c['COLUMN_NAME']))$default='[redacted]';$md.='| `'.$c['COLUMN_NAME'].'` | `'.$cell($c['COLUMN_TYPE']).'` | '.$c['IS_NULLABLE'].' | `'.$cell($default).'` | '.$cell($c['EXTRA'])." |\n";}
        $md.="\n| Index | Kind | Ordered columns / prefix |\n|---|---|---|\n";$group=[];foreach($indexes as $i)$group[$i['INDEX_NAME']][]=$i;
        $erd.="    $name {\n";
        foreach($group as $index=>$parts){$fields=array_map(fn($p)=>$p['COLUMN_NAME'].($p['SUB_PART']?'('.$p['SUB_PART'].')':''),$parts);$md.='| `'.$index.'` | '.($index==='PRIMARY'?'PRIMARY':((int)$parts[0]['NON_UNIQUE']===0?'UNIQUE':'INDEX')).' | `'.implode('`, `',$fields)."` |\n";if($index==='PRIMARY')foreach($parts as $p){$c=array_values(array_filter($columns,fn($c)=>$c['COLUMN_NAME']===$p['COLUMN_NAME']))[0];$type=preg_replace('/[^A-Za-z0-9_]/','_',strtok($c['COLUMN_TYPE'],'('));$erd.='        '.$type.' '.$p['COLUMN_NAME']." PK\n";}}
        $erd.="    }\n";
        if($relationships){$md.="\n| FK | Child column | Parent | Delete / update |\n|---|---|---|---|\n";foreach($relationships as $r)$md.='| `'.$r['CONSTRAINT_NAME'].'` | `'.$r['COLUMN_NAME'].'` | `'.$r['REFERENCED_TABLE_NAME'].'.'.$r['REFERENCED_COLUMN_NAME'].'` | '.$r['DELETE_RULE'].' / '.$r['UPDATE_RULE']." |\n";}else $md.="\nNo declared outbound foreign key.\n";
    }
    foreach($data['relationships'] as $r){$c=array_values(array_filter($data['columns'],fn($c)=>$c['TABLE_NAME']===$r['TABLE_NAME']&&$c['COLUMN_NAME']===$r['COLUMN_NAME']))[0];$singleUnique=false;$groups=[];foreach($data['indexes'] as $i)if($i['TABLE_NAME']===$r['TABLE_NAME']&&(int)$i['NON_UNIQUE']===0)$groups[$i['INDEX_NAME']][]=$i['COLUMN_NAME'];foreach($groups as $fields)if($fields===[$r['COLUMN_NAME']])$singleUnique=true;$erd.='    '.$r['REFERENCED_TABLE_NAME'].' '.($c['IS_NULLABLE']==='YES'?'|o':'||').'--'.($singleUnique?'o|':'o{').' '.$r['TABLE_NAME'].' : "'.$r['COLUMN_NAME'].'"'."\n";}
    $erd.="```\n\n`booking.DriverID`, `user.StationID` and booking GPS columns remain current-state caches; assignment/tracking tables retain new history. Original cascade rules shown in the schema are not permission to delete historical records. See [DATABASE_BACKUP_RESTORE.md](DATABASE_BACKUP_RESTORE.md) for non-destructive deployment/recovery.\n";
    file_put_contents(__DIR__.'/../docs/DATABASE_SCHEMA.md',$md);file_put_contents(__DIR__.'/../docs/DATABASE_ERD.md',$erd);
    echo "Schema and ERD documentation generated from metadata.\n";
}catch(Throwable $e){fwrite(STDERR,"Schema documentation generation failed.\n");exit(1);}
